#include <math.h>

float vectorized_s318(int iterations, int LEN_1D, float* a, int inc)
{
    int k, index;
    float max, chksum;
    chksum = 0.0f;
    max = 0.0f;
    index = 0;
    for (int nl = 0; nl < iterations/2; nl++) {
        k = 0;
        index = 0;
        max = fabsf(a[0]);
        k += inc;

        float cur_max = max;
        int cur_idx = 0;

        int i = 1;
        int end4 = LEN_1D - 3;

        for (; i < end4; i += 4) {
            float v0 = fabsf(a[k]);
            float v1 = fabsf(a[k + inc]);
            float v2 = fabsf(a[k + 2*inc]);
            float v3 = fabsf(a[k + 3*inc]);

            if (v0 > cur_max) { cur_max = v0; cur_idx = i; }
            if (v1 > cur_max) { cur_max = v1; cur_idx = i+1; }
            if (v2 > cur_max) { cur_max = v2; cur_idx = i+2; }
            if (v3 > cur_max) { cur_max = v3; cur_idx = i+3; }

            k += 4*inc;
        }

        for (; i < LEN_1D; i++) {
            float v = fabsf(a[k]);
            if (v > cur_max) {
                cur_max = v;
                cur_idx = i;
            }
            k += inc;
        }

        max = cur_max;
        index = cur_idx;

        chksum = max + (float)index;
    }
    return chksum;
}

float s318_opt(int iterations, int LEN_1D, float* a, int inc) {
    int k, index;
    float max, chksum;

    for (int nl = 0; nl < iterations/2; nl++) {
        k = 0;
        index = 0;
        max = fabsf(a[0]);
        k += inc;

        // Split the loop: first handle the comparison values
        float max_val = max;
        int max_index = index;

        // Process all elements to find maximum absolute value
        for (int i = 1; i < LEN_1D; i++) {
            float current_abs = fabsf(a[k]);
            // Store comparison result
            int is_greater = (current_abs > max_val);
            // Update using arithmetic to avoid branching
            max_val = is_greater ? current_abs : max_val;
            k += inc;
        }

        // Second pass: find the first index where value equals max_val
        k = inc; // Reset to first element
        for (int i = 1; i < LEN_1D; i++) {
            float current_abs = fabsf(a[k]);
            if (current_abs == max_val) {
                max_index = i;
                break; // Found first occurrence
            }
            k += inc;
        }

        max = max_val;
        index = max_index;
        chksum = max + (float)index;
    }
    return max + index + 1;
}
